        mirror.value = el.value.slice(0, el.selectionEnd ?? el.value.length)
        el.parentNode.insertBefore(mirror, el.nextSibling)
        const lines = Math.max(1, Math.round((mirror.scrollHeight - padT - padB) / lh))
