      writeFileSync(projectShared, JSON.stringify({ mcpServers: { 'shared-search': { args: ['--fast'] }, 'repo-tools': { command: 'node', args: ['tools/repo-mcp.js'] } } }))
      writeFileSync(projectPi, JSON.stringify({ mcpServers: { 'pi-only': { disabled: true } } }))

